<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,MorphTo};
class FinancialCommitment extends Model { use \App\Traits\HasCompany; public const STATUSES=['draft','committed','released','fulfilled','cancelled']; protected $attributes=['status'=>'draft']; protected $fillable=['company_id','project_id','budget_item_id','budget_line_id','source_type','source_id','party_id','reference_number','description','amount','currency','budget_amount','exchange_rate_to_budget','notes','created_by']; protected $casts=['amount'=>'decimal:4','budget_amount'=>'decimal:4','exchange_rate_to_budget'=>'decimal:8','committed_at'=>'datetime','released_at'=>'datetime']; public function project():BelongsTo{return $this->belongsTo(Project::class);} public function item():BelongsTo{return $this->belongsTo(BudgetItem::class,'budget_item_id');} public function line():BelongsTo{return $this->belongsTo(BudgetLine::class,'budget_line_id');} public function party():BelongsTo{return $this->belongsTo(Party::class);} public function source():MorphTo{return $this->morphTo();} public function amendments():HasMany{return $this->hasMany(FinancialCommitmentAmendment::class);} public function actualCosts():HasMany{return $this->hasMany(ActualCost::class);} public function effectiveBudgetAmount():float{return (float)$this->budget_amount+(float)$this->amendments()->where('status','approved')->sum('budget_amount_change');} }
